    for (let i = 0; i < pathList.length; i++) {
      let editorTag = pathList[i][src].match(regExp);
      if (editorTag) {
        path = editorTag[0];
        break;
      }
    }
    if (path === "") path = pathList.length > 0 ? pathList[0][src] : "";
