var STAFF_ENDPOINT = "/api/staff/v1/people";
function searchStaff(q4) {
  const query2 = toQueryString({
    q: q4,
    fields: [
      "id",
      "name",
      "email",
      "username",
      "organisation",
      "department"
    ].join(",")
  });
  return N2(`${STAFF_ENDPOINT}${q4 ? "?" + query2 : ""}`).pipe(map((list2) => list2.map((item) => new StaffUser(item))));
}
function showStaff(id) {
  return N2(`${STAFF_ENDPOINT}/${encodeURIComponent(id)}`).pipe(map((item) => new StaffUser(item)));
}

